# Сборка документа «Модель монетизации StepPay» (ГОСТ 7.32-2017, список источников по ГОСТ Р 7.0.100-2018).
from gostdoc import build, AL
from build_problem import Note, ORG, AUTHOR, ACCESS
import natives as nv

TITLE = "Модель монетизации проекта StepPay"
KIND = ""


def make(pages):
    D = Note()
    D.total = pages.get("__total__", "[N]")
    D.approval_and_title(ORG, TITLE, KIND, "", "Автор проекта", "2026", "", AUTHOR)
    entries = [
        (1, "ВВЕДЕНИЕ"),
        (1, "1 ПРИНЦИПЫ МОНЕТИЗАЦИИ"),
        (1, "2 ИСТОЧНИКИ ВЫРУЧКИ И ТАРИФЫ"),
        (1, "3 ЭКОНОМИКА СДЕЛКИ И ТОЧКА БЕЗУБЫТОЧНОСТИ"),
        (1, "4 ВЫГОДА ЗАКАЗЧИКА"), (2, "4.1 Сервис без комиссии"), (2, "4.2 Цена с гарантией оплаты"), (2, "4.3 Неустойка за просрочку этапа"), (2, "4.4 Сравнение с другими способами оплаты"),
        (1, "5 ПРОГНОЗ ВЫРУЧКИ"),
        (1, "6 РИСКИ МОДЕЛИ И ОГРАНИЧЕНИЯ"),
        (1, "ЗАКЛЮЧЕНИЕ"),
        (1, "СПИСОК ИСПОЛЬЗОВАННЫХ ИСТОЧНИКОВ"),
    ]
    D.toc(entries, pages)

    def unnumbered(title):
        D.headings.append((1, title))
        D.center(title, bold=True, after=8)

    unnumbered("ВВЕДЕНИЕ")
    D.p("Документ описывает, как проект StepPay получает выручку, сколько платят участники и почему заказчику выгодно пользоваться сервисом. Расчеты согласованы с документом об анализе рынка: оборот сделок 6,4 млрд руб. в первый год, 32 млрд руб. во второй и 50 млрд руб. на третий год, комиссия 1,5 %. Средний чек принят равным 300 000 руб.: в доступный объем рынка входят направления с крупной предоплатой (строительство и ремонт под ключ, мероприятия, диджитал-проекты), а закупка материалов может быть отдельным этапом сделки. Средний чек является допущением; при среднем чеке 150 000 руб. показатели пересчитаны в финансовой модели. Значения тарифов и объемов являются плановыми и уточняются на пилоте.")
    D.p("Суть продукта: заказчик резервирует всю сумму сделки смарт-контрактом на платформе цифрового рубля, а средства высвобождаются исполнителю по мере приемки этапов. Резерв StepPay не называется эскроу. По статье 860.7 Гражданского кодекса РФ [5] счет эскроу открывает банк (эскроу-агент) по трехстороннему договору с депонентом и бенефициаром, в котором определены основания и срок передачи средств; эти условия могут содержаться и в ином договоре с участием банка-эскроу-агента (пункт 2 статьи 860.7). В StepPay средства не размещаются на счете эскроу, а блокируются условиями смарт-контракта сделки на платформе цифрового рубля. Если юридическая проработка покажет, что сделку целесообразно оформлять с ВТБ в роли эскроу-агента, термин может быть использован.")

    D.h1("1", "Принципы монетизации")
    D.p("Модель построена на пяти принципах:")
    D.p("а) вся сумма сделки до начала работ резервируется смарт-контрактом сделки на платформе цифрового рубля и высвобождается по этапам: после приемки этапа его сумма переходит исполнителю, при отказе или истечении сроков остаток возвращается заказчику;")
    D.p("б) заказчик не платит комиссию: сервис для него бесплатен;")
    D.p("в) исполнитель платит 1,5 % с полученной оплаты за гарантию, что оплата обеспечена до начала работы; это в несколько раз ниже комиссий площадок с безопасной сделкой;")
    D.p("г) просрочка этапа обходится исполнителю неустойкой в пользу заказчика: смарт-контракт удерживает ее из суммы этапа автоматически, без претензий и суда;")
    D.p("д) регистрация и создание сделки бесплатны для обеих сторон, дополнительные возможности предлагаются по подписке.")

    D.h1("2", "Источники выручки и тарифы")
    D.p("Источники выручки и плановые тарифы приведены в таблице 1.")
    D.table("Источники выручки", ["Источник", "Кто платит", "Тариф", "Когда"], [
        ["Комиссия за гарантию оплаты", "Исполнитель", "1,5 % от выплаченной суммы", "При выплате за принятый этап"],
        ["Подписка Pro", "Исполнитель", "490 руб. в месяц", "Помесячно: приоритет в каталоге, отметка «Проверено», шаблоны этапов, аналитика"],
        ["Сборы (краудфандинг)", "Автор проекта", "3 % от выплаченных сумм", "При выплате за этап, принятый спонсорами"],
        ["Гранты (организациям)", "Фонд, грантодатель", "Договор на сопровождение программы", "За программу: настройка этапов, отчетность, контроль выплат"],
        ["Сопровождение спора", "Сторона, открывшая спор", "1 000 руб., 70 % получает приемщик", "При открытии спора"],
        ["Лицензирование другим банкам", "Банк", "Доля дохода по договору", "После запуска в ВТБ Онлайн; в прогнозе выручки не учитывается"],
    ], [3.6, 3.4, 3.9, 5.6], size=10)
    D.p("Для заказчика сервис бесплатен, а комиссия исполнителя в несколько раз ниже, чем у площадок с безопасной сделкой (рисунок 1) [1; 2; 3]. Неустойка за просрочку выручкой платформы не является: она полностью возвращается заказчику.")
    D.chart(nv.fees(), "Комиссии площадок с защитой сделки и StepPay, % от суммы заказа")

    D.h1("3", "Экономика сделки и точка безубыточности")
    D.p("При среднем чеке 300 000 руб. комиссия исполнителя 1,5 % дает 4 500 руб. выручки со сделки. Переменные расходы (проверка участников, плата за операции, поддержка, доля приемщиков) оценены в 1 000 руб., вклад со сделки составляет 3 500 руб. (рисунок 2).")
    D.chart(nv.unit(), "Экономика одной сделки, руб.")
    D.p("На старте при постоянных расходах 5 млн руб. в месяц (команда, инфраструктура, юридическое сопровождение, привлечение пользователей) точка безубыточности составляет около 1 430 сделок в месяц, это около 5,1 млрд руб. оборота в год. С ростом продукта постоянные расходы увеличиваются до 20 млн руб. в месяц на третьем году, и порог поднимается до 5 700 сделок в месяц (рисунок 3). План третьего года, около 13 900 сделок в месяц, превышает его в 2,4 раза. Каждая сделка сверх порога увеличивает прибыль на 3 500 руб. Рост среднего чека и доли повторных сделок снижает порог.")
    D.chart(nv.breakeven(), "Точка безубыточности по числу сделок в месяц")

    D.h1("4", "Выгода заказчика")
    D.p("Заказчик резервирует всю сумму сделки заранее, поэтому сервис должен давать ему выгоду помимо защиты от потери аванса. Предусмотрены три механизма.")
    D.h2("4.1", "Сервис без комиссии")
    D.p("Заказчик не платит за сделку: комиссию 1,5 % платит исполнитель с полученной оплаты. На площадках с безопасной сделкой исполнитель отдает от 7 до 20 % [1; 2; 3] и закладывает эту комиссию в цену работ, поэтому ее в итоге оплачивает заказчик. Разница с комиссией StepPay составляет от 5,5 до 18,5 % суммы, на ремонте за 300 000 руб. это от 16,5 до 55,5 тыс. руб., которые исполнитель может не включать в цену. Сравнение относится к сделкам на площадках; при прямой договоренности с мастером без посредника выгода заказчика состоит в защите средств (раздел 4.4), а не в цене.")
    D.h2("4.2", "Цена с гарантией оплаты")
    D.p("Исполнитель видит, что вся сумма сделки уже зарезервирована и оплата каждого этапа обеспечена до начала работы. Ему не нужно тратить время на получение аванса и взыскание долгов, поэтому он может указать в каталоге цену при оплате через StepPay со скидкой за гарантию. Скидка 3 % на ремонте за 300 000 руб. дает заказчику 9 тыс. руб. (рисунок 4). Размер скидки является гипотезой: готовность исполнителей платить комиссию и снижать цену за гарантию оплаты проверяется опросом в ноябре 2026 года (гипотезы H4 и H7 в документе об анализе проблемы) и на пилоте.")
    D.h2("4.3", "Неустойка за просрочку этапа")
    D.p("В условия контракта включаются ставка неустойки и ее предельный размер, например 0,5 % суммы этапа за каждый день просрочки, но не более 10 % этапа. Если исполнитель сдал этап позже срока, при приемке смарт-контракт выплачивает ему сумму этапа за вычетом неустойки, а неустойка возвращается заказчику из того же резерва. Если неустойка достигла предела, а этап не сдан, сделка прекращается и остаток резерва возвращается заказчику.")
    D.p("Пример: этап стоимостью 90 тыс. руб. сдан с опозданием на 6 дней. Неустойка составляет 3 % этапа, 2,7 тыс. руб., исполнитель получает 87,3 тыс. руб. Неустойка не начисляется, если задержка вызвана заказчиком: работа, сданная в срок, принимается автоматически по истечении срока проверки.")
    D.chart(nv.stepwise(), "Выгода заказчика на ремонте за 300 000 руб., тыс. руб.")
    D.h2("4.4", "Сравнение с другими способами оплаты")
    D.p("Сравнение способов оплаты той же работы приведено в таблице 2. Проценты на резерв не начисляются: средства находятся в резерве сделки в цифровых рублях, а на остаток цифровых рублей проценты не начисляются [4].")
    D.table("Сравнение способов оплаты для заказчика", ["Способ", "Риск заказчика", "Расходы и выгода заказчика"], [
        ["Аванс исполнителю", "Потеря аванса при срыве работ", "Неустойку при просрочке взыскивать через претензию или суд"],
        ["Безопасная сделка на площадке", "Деньги у посредника, спор по правилам площадки", "Комиссия от 7 до 20 %, выплата за заказ целиком"],
        ["Оплата после работ", "Исполнитель не начинает без гарантии", "Работа не начинается или дорожает"],
        ["StepPay: резерв сделки с выплатой по этапам", "Выплата только за принятый этап, остаток возвращается", "Комиссии для заказчика нет, скидка за гарантию оплаты, неустойка удерживается автоматически"],
    ], [4.6, 5.4, 6.5], size=10)

    D.h1("5", "Прогноз выручки")
    D.p("Прогноз построен на допущениях, приведенных в таблице 3. Выручка по годам показана на рисунке 5.")
    D.table("Допущения прогноза", ["Показатель", "1-й год", "2-й год", "3-й год"], [
        ["Доля доступного объема рынка (SAM)", "около 1,0 %", "около 5,2 %", "около 8,1 %"],
        ["Оборот сделок, млн руб. в год", "6 400", "32 000", "50 000"],
        ["Сделок в месяц (средний чек 300 000 руб.)", "около 1 780", "около 8 890", "около 13 890"],
        ["Комиссия исполнителя 1,5 %, млн руб.", "96,0", "480,0", "750,0"],
        ["Подписчиков Pro", "2 000", "10 000", "20 000"],
        ["Подписка, млн руб.", "11,8", "58,8", "117,6"],
        ["Сборы (3 % от 100, 400, 1 000 млн руб.) и гранты, млн руб.", "5,0", "20,0", "50,0"],
        ["Споры (3 % сделок, 300 руб. платформе), млн руб.", "0,2", "1,0", "1,5"],
        ["Итого выручка, млн руб.", "113,0", "559,8", "919,1"],
    ], [7.6, 3.0, 3.0, 2.9], size=11)
    D.chart(nv.revenue(), "Прогноз выручки по источникам, млн руб.")
    D.p("Безубыточность по прибыли до вычета амортизации (EBITDA) достигается в первом году продаж при выходе на 1 430 сделок в месяц; чистая прибыль с учетом амортизации вложений в платформу положительна со второго года продаж (финансовая модель для банка ВТБ). Основной канал роста составляет приложение ВТБ Онлайн, в которое встраивается поэтапная оплата для клиентов с цифровым рублем; подключение других банков рассматривается после запуска и в прогноз не включено. Основной источник выручки во всех годах составляет комиссия исполнителя (от 82 до 86 %), что делает модель зависимой от объема сделок, поэтому дополнительные источники (подписка, сборы, гранты) развиваются параллельно.")

    D.h1("6", "Риски модели и ограничения")
    D.p("а) Объем сделок ниже плана: выручка пропорциональна числу сделок. Мера: пилот в одном сегменте с высоким чеком (ремонт), рост через рекомендации исполнителей.")
    D.p("б) Исполнители включают комиссию в цену. Мера: комиссия 1,5 % в несколько раз ниже рыночной и окупается для исполнителя гарантией оплаты и отсутствием затрат на взыскание долгов.")
    D.p("в) Споры о причинах просрочки. Мера: сроки этапов и ставка неустойки фиксируются в подписанном контракте, стороны могут продлить срок по взаимному согласию, спор о неустойке решает независимый приемщик.")
    D.p("г) Регуляторные ограничения на взимание платы в расчетах цифровыми рублями. Мера: плата взимается за сервис сделки, а не за перевод, переводы выполняют банки на платформе цифрового рубля по своим тарифам.")
    D.p("д) Зависимость от сроков платформы коммерческих смарт-контрактов и интеграции в ВТБ Онлайн. Мера: переносимая архитектура, работа на эмуляторе и в тестовой сети до запуска платформы, пилот в одном сегменте до полной интеграции.")
    D.p("е) Готовность исполнителей платить комиссию 1,5 % и давать скидку за гарантию не подтверждена данными пользователей. Мера: опрос и интервью в ноябре 2026 года с заранее заданными порогами; при низкой готовности рассматривается разделение комиссии между сторонами или комиссия 1 % (чувствительность приведена в финансовой модели).")
    D.p("ж) Допущения о числе подписчиков, объеме сборов и грантов, размере скидок исполнителей не подтверждены и проверяются на пилоте.")

    D.pagebreak()
    unnumbered("ЗАКЛЮЧЕНИЕ")
    D.p("Вся сумма сделки резервируется смарт-контрактом на платформе цифрового рубля и высвобождается исполнителю по мере приемки этапов. Заказчик не платит комиссию, получает скидку за гарантию оплаты и неустойку при просрочке этапа, которую смарт-контракт удерживает автоматически.")
    D.p("Основной источник выручки StepPay составляет комиссия исполнителя 1,5 % с выплаченных за принятые этапы сумм, в несколько раз ниже комиссий площадок с безопасной сделкой. Вклад со сделки составляет 3 500 руб., точка безубыточности около 1 430 сделок в месяц на старте и 5 700 на третьем году, прогноз выручки на третий год 919,1 млн руб. при обороте сделок 50 млрд руб. Дополнительные источники выручки: подписка для исполнителей, комиссия со сборов, сопровождение грантовых программ и споров; в перспективе возможно лицензирование решения другим банкам.")

    D.pagebreak()
    unnumbered("СПИСОК ИСПОЛЬЗОВАННЫХ ИСТОЧНИКОВ")
    srcs = [
        "На FL.ru вводится новая комиссия по безопасной сделке // Блог FL.ru. URL: https://blog.fl.ru/whats-new-may4 " + ACCESS + ".",
        "Биржа фриланса 2026: рейтинг 15 лучших фриланс-бирж // vc.ru. URL: https://vc.ru/hr/3035231-reyting-luchshikh-frilans-birzh " + ACCESS + ".",
        "Биржи фриланса 2026: комиссии, вывод денег, где заказы // BuyHold. URL: https://buyhold.ru/birzhi-frilansa/ " + ACCESS + ".",
        "Комиссии за переводы, вклады и кредиты: ЦБ дал инструкцию по цифровому рублю // Российская газета. 2023. 24 июля. URL: https://rg.ru/2023/07/24/komissii-za-perevody-vklady-i-kredity-cb-dal-instrukciiu-po-cifrovomu-rubliu.html " + ACCESS + ".",
        "Гражданский кодекс Российской Федерации (часть вторая) от 26.01.1996 № 14-ФЗ. Статья 860.7. Договор счета эскроу // КонсультантПлюс. URL: https://www.consultant.ru/document/cons_doc_LAW_9027/ (дата обращения: 31.10.2026).",
    ]
    for i, s in enumerate(srcs, 1):
        D.src(i, s)
    return D


if __name__ == "__main__":
    build(make, "StepPay_Monetization")
    print("ok")
